function expandTuple(tuple, index) {
  const [hash, title, category, badge, studio] = tuple;
  return {
    id: `gm-${hash}`,
    title,
    category,
    badge: badge || "HTML5",
    studio: studio || (badge === "3D WebGL" ? "Free 3D WebGL • Instant Play" : "Free HTML5 • Instant Play"),
    thumb: `https://img.gamemonetize.com/${hash}/512x384.jpg`,
    url: `https://html5.gamemonetize.co/${hash}/`,
    directEmbed: true,
  };
}

const ALL_GAMES = [
  ...CURATED_AAA_AND_VIRAL.slice(0, 26).map(expandTuple),
  SPECIAL_DIRECT_GAMES[0],
  ...CURATED_AAA_AND_VIRAL.slice(26).map(expandTuple),
  SPECIAL_DIRECT_GAMES[1],
  ...EXTRA_HTML5_GAMES.map(expandTuple),
];

const CACHED_PAYLOAD = JSON.stringify({
  total: ALL_GAMES.length,
  aaaCount: ALL_GAMES.filter((g) => g.category === "aaa").length,
  games: ALL_GAMES,
});

export default function gamesHandler(_req, res) {
  res.setHeader("Access-Control-Allow-Origin", "*");
  res.setHeader("Cache-Control", "public, max-age=3600");
  res.setHeader("Content-Type", "application/json; charset=utf-8");
  res.writeHead(200);
  res.end(CACHED_PAYLOAD);
}
